function renderSimCards(){if(sim&&!$('#simSession').classList.contains('hidden'))return;$('#simulationCards').classList.remove('hidden');$('#simulationCards').innerHTML=SIMS.map(s=>`<article class="sim-card ${s.featured?'featured-sim':''}"><div class="sim-card-head"><span class="board">${s.board}</span>${s.featured?'<span class="recommended">PRF ADM</span>':''}</div><h3>${s.title}</h3><p>${s.desc}</p><div class="sim-data"><span>${s.count} itens</span><span>${s.format}</span><span>Pontuação ${s.scoring}</span></div><button class="btn primary" data-start-sim="${s.id}">Iniciar simulado</button></article>`).join('');$$('[data-start-sim]').forEach(b=>b.onclick=()=>startSim(b.dataset.startSim))}
function weightedPool(careerId,count){const p=profile(careerId),all=curated.filter(q=>q.careers.includes(careerId)),chosen=[],used=new Set();const normalized=s=>{if(careerId==='pcdf'&&s==='Matemática e Raciocínio Lógico')return ['Matemática e Raciocínio Lógico','Raciocínio Lógico'];if(careerId==='pcdf'&&s==='Conhecimentos sobre DF / RIDE')return ['Conhecimentos sobre DF / RIDE','Realidade do DF e Entorno'];return [s]};p.dist.forEach(([sub,n])=>{const want=Math.max(1,Math.round(count*n/p.total));const cand=shuffle(all.filter(q=>normalized(sub).includes(q.subject)&&!used.has(q.id)));cand.slice(0,want).forEach(q=>{chosen.push(q);used.add(q.id)})});shuffle(all.filter(q=>!used.has(q.id))).slice(0,Math.max(0,count-chosen.length)).forEach(q=>chosen.push(q));return shuffle(chosen).slice(0,count)}
function simQuestion(q){if(!sim)return q;const base={...q,_career:sim.careerId||sim.id};if(sim.mode==='cebraspe')return {...base,_forceCE:true,_bankLabel:'CEBRASPE • CERTO/ERRADO',contextType:q.contextType||'SITUAÇÃO HIPOTÉTICA',examCommand:'Julgue o item conforme a situação e a regra aplicável.'};if(sim.mode==='quadrix')return {...base,_bankLabel:'QUADRIX • MÚLTIPLA ESCOLHA',contextType:q.contextType||'CASO PRÁTICO',examCommand:q.examCommand||'Considerando a situação apresentada, assinale a alternativa correta.'};if(sim.mode==='funcab')return {...base,_bankLabel:'FUNCAB • REFERÊNCIA 2014'};if(sim.mode==='aocp')return {...base,_bankLabel:'AOCP • 2022'};return base}
function startSim(id){const def=SIMS.find(x=>x.id===id),careerId=def.careerId||id,items=weightedPool(careerId,def.count);sim={...def,careerId,items,index:0,answers:{},reasons:{},review:false};$('#simulationCards').classList.add('hidden');$('.bank-lab')?.classList.add('hidden');$('.sim-section-title')?.classList.add('hidden');$('#simResult').classList.add('hidden');$('#simSession').classList.remove('hidden');$('#simBoard').textContent=def.board;$('#simTitle').textContent=def.title;simStartedAt=Date.now();clearInterval(timerHandle);timerHandle=setInterval(updateTimer,1000);updateTimer();renderSimQuestion()}
function fmtTime(ms){const s=Math.floor(ms/1000),m=Math.floor(s/60),r=s%60;return `${String(m).padStart(2,'0')}:${String(r).padStart(2,'0')}`}
function updateTimer(){if(!sim)return;const t=fmtTime(Date.now()-simStartedAt);$('#simTimer').textContent=t;$('#simTimeSmall').textContent=t}
function captureSim(){if(!sim)return;const ans=selected('sim-answer'),reason=$('#sim-reason')?.value||'';if(ans!==null)sim.answers[sim.index]=ans;sim.reasons[sim.index]=reason}
function renderSimQuestion(){const q=simQuestion(sim.items[sim.index]);$('#simQuestion').innerHTML=questionMarkup(q,sim.index,sim.items.length,'sim',{showCorrection:sim.review,locked:sim.review});$('#simPosition').textContent=`${sim.index+1} / ${sim.items.length}`;$('#simProgress').style.width=((sim.index+1)/sim.items.length*100)+'%';$('#simAnswered').textContent=Object.keys(sim.answers).length;const prev=$('#simQuestion [data-qnav="prev"]'),next=$('#simQuestion [data-qnav="next"]');prev.onclick=()=>{if(!sim.review)captureSim();if(sim.index>0){sim.index--;renderSimQuestion()}};next.onclick=()=>{if(!sim.review)captureSim();if(sim.index<sim.items.length-1){sim.index++;renderSimQuestion()}}}
$('#finishSim').onclick=()=>{if(!sim)return;captureSim();clearInterval(timerHandle);let hits=0,wrong=0,answered=0;sim.items.forEach((raw,i)=>{const q=simQuestion(raw),nq=normalizeQuestion(q,sim.careerId),a=sim.answers[i];if(a!==undefined){answered++;if(a===nq.displayCorrect)hits++;else wrong++}if(a!==nq.displayCorrect)saveError(q,nq,a??null,sim.reasons[i]||'',`Simulado ${sim.board}`,sim.careerId)});const blank=sim.items.length-answered,elapsed=Date.now()-simStartedAt,isRisk=sim.mode==='cebraspe',net=isRisk?hits-wrong:hits,pct=Math.round(hits/sim.items.length*100);sim.review=true;$('#simSession').classList.add('hidden');$('#simResult').classList.remove('hidden');$('#simResult').innerHTML=`<span class="kicker">RESULTADO • ${sim.board}</span><h2>${isRisk?`Pontuação líquida: ${net}`:`${hits} acertos em ${sim.items.length}`}</h2><div class="result-numbers"><div><b>${hits}</b><span>acertos</span></div><div><b>${wrong}</b><span>erros${isRisk?' (−1 cada)':''}</span></div><div><b>${blank}</b><span>em branco</span></div><div><b>${pct}%</b><span>acerto bruto</span></div><div><b>${fmtTime(elapsed)}</b><span>tempo total</span></div></div><p>${isRisk?'Neste treino Cebraspe, o erro retirou um ponto e a omissão valeu zero. Isso força você a decidir quando tem segurança suficiente para marcar.':'Neste treino de múltipla escolha, erros não retiram pontos. O foco é comparar distratores e localizar a única alternativa tecnicamente correta.'}</p><p>Os erros foram enviados ao Caderno de Erros. Na revisão, abra cada item para conferir resolução, pegadinha e fundamento.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="reviewSim">Revisar prova</button><button class="btn secondary" id="closeSimResult">Voltar aos simulados</button></div>`;$('#reviewSim').onclick=()=>{sim.index=0;$('#simResult').classList.add('hidden');$('#simSession').classList.remove('hidden');$('#finishSim').classList.add('hidden');renderSimQuestion()};$('#closeSimResult').onclick=exitSim;renderReview()};
$('#exitSim').onclick=exitSim;function exitSim(){clearInterval(timerHandle);sim=null;$('#simSession').classList.add('hidden');$('#simResult').classList.add('hidden');$('#finishSim').classList.remove('hidden');$('#simulationCards').classList.remove('hidden');$('.bank-lab')?.classList.remove('hidden');$('.sim-section-title')?.classList.remove('hidden');renderSimCards()}



