function renderWritingPrompt(){const t=writingTheme(),bank=WRITING_BANKS[$('#writingBank').value];if(!t||!bank)return;$('#writingPrompt').innerHTML=`<div class="prompt-bank"><b>${bank.name} • SIMULAÇÃO AUTORAL</b><span>${bank.label}</span></div><h3>${esc(t.title)}</h3><div class="stimulus">${esc(t.stimulus)}</div><p class="command">${esc(t.command)}</p><ol>${t.aspects.map(a=>`<li>${esc(a.label)}</li>`).join('')}</ol><span class="prompt-note">Configuração de treino: produza um texto de aproximadamente 25 a 30 linhas. Em prova real, siga exclusivamente o limite do edital e o comando da folha.</span>`;const draft=writingDrafts()[t.id];if(draft&&$('#writingText').value.trim()===''){$('#writingText').value=draft.text||'';$('#planThesis').value=draft.plan?.thesis||'';$('#planArg1').value=draft.plan?.arg1||'';$('#planArg2').value=draft.plan?.arg2||'';$('#planConclusion').value=draft.plan?.conclusion||'';updateWritingMetrics()}}
function writingWords(text){return (text.match(/[A-Za-zÀ-ÖØ-öø-ÿ0-9]+(?:['’\-][A-Za-zÀ-ÖØ-öø-ÿ0-9]+)*/g)||[])}
function writingParagraphs(text){return text.trim()?text.trim().split(/\n+/).map(x=>x.trim()).filter(Boolean):[]}
function updateWritingMetrics(){const text=$('#writingText')?.value||'',w=writingWords(text),pars=writingParagraphs(text);if($('#writingWords'))$('#writingWords').textContent=w.length;if($('#writingLines'))$('#writingLines').textContent=w.length?Math.max(text.split('\n').filter(x=>x.trim()).length,Math.ceil(w.length/10)):0;if($('#writingParagraphs'))$('#writingParagraphs').textContent=pars.length}
function saveWritingDraft(silent=false){const t=writingTheme();if(!t)return;const d=writingDrafts();d[t.id]={bank:$('#writingBank').value,text:$('#writingText').value,plan:{thesis:$('#planThesis').value,arg1:$('#planArg1').value,arg2:$('#planArg2').value,conclusion:$('#planConclusion').value},savedAt:Date.now()};save(LS.writingDrafts,d);if(!silent)toast('Rascunho salvo neste navegador')}
function skeletonForTheme(){const t=writingTheme();return `[INTRODUÇÃO]\nContextualize: ${t.title}. Delimite o problema e escreva sua tese em uma frase, indicando os dois eixos que serão desenvolvidos.\n\n[DESENVOLVIMENTO 1]\nApresente o primeiro argumento (${t.axes[0]}). Explique a relação de causa e efeito, acrescente fundamento ou exemplo e ligue o raciocínio à tese.\n\n[DESENVOLVIMENTO 2]\nDesenvolva o segundo eixo (${t.axes[1]}), sem repetir o parágrafo anterior. Demonstre por que esse ponto altera a análise do tema.\n\n[CONCLUSÃO]\nRetome a tese com outras palavras, sintetize os argumentos e responda diretamente ao comando. Acrescente encaminhamento apenas se ele for exigido.`}
function normText(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function countHits(text,keys){const n=normText(text);return keys.filter(k=>n.includes(normText(k))).length}
function analyzeWriting(text,t,bankId){const words=writingWords(text),pars=writingParagraphs(text),sent=text.split(/[.!?]+/).map(x=>x.trim()).filter(Boolean);const n=normText(text),issues=[];const add=(severity,title,why,fix,example='')=>issues.push({severity,title,why,fix,example});
const aspectStatus=t.aspects.map(a=>({label:a.label,ok:countHits(text,a.keys)>0}));const aspectCovered=aspectStatus.filter(x=>x.ok).length;
const themeHits=countHits(text,t.keywords);let adherence=Math.min(20,6+themeHits*2+aspectCovered*2);if(words.length<100)adherence=Math.min(adherence,10);if(themeHits<2)add('high','Aderência ao tema ainda fraca','Poucos conceitos centrais do tema aparecem de forma identificável.','Volte ao comando e faça cada parágrafo responder a uma parte dele. Não acrescente assunto lateral.',`Use os eixos: ${t.axes.join(' / ')}.`);
aspectStatus.filter(x=>!x.ok).forEach(x=>add('high','Aspecto do comando possivelmente não desenvolvido',x.label,'Inclua um trecho específico que responda a esse aspecto com explicação e consequência.'));
let structure=pars.length>=4?20:pars.length===3?15:pars.length===2?9:4;if(pars.length<4)add('high','Estrutura pouco controlada',`Foram identificados ${pars.length} parágrafo(s).`,'Para este treino, organize introdução, dois desenvolvimentos e conclusão. Depois ajuste se o edital/comando pedir outra estrutura.');
const first=pars[0]||'',last=pars[pars.length-1]||'';const thesisMarkers=['deve','é necessário','e necessario','é essencial','e essencial','torna-se','mostra-se','evidencia-se','sustenta-se','defende-se','exige','depende de'];const hasThesis=thesisMarkers.some(k=>normText(first).includes(normText(k)))||($('#planThesis')?.value||'').trim().length>8;let argument=hasThesis?8:4;if(!hasThesis)add('medium','Tese pouco explícita','A introdução não deixa clara, de forma facilmente detectável, a posição central que o texto defenderá.','Feche a introdução com uma afirmação que responda diretamente ao tema e antecipe a lógica dos desenvolvimentos.',`Ex.: “Nesse cenário, ${t.axes[0]} e ${t.axes[1]} constituem eixos decisivos para enfrentar a questão.”`);
const mid=pars.slice(1,-1);argument+=Math.min(12,mid.length*4+Math.min(4,countHits(mid.join(' '),['porque','pois','uma vez que','em razão','por isso','consequ','exemplo','dados','princípio','lei','norma'])));if(mid.length<2)add('medium','Argumentação concentrada demais','Há menos de dois parágrafos de desenvolvimento.','Separe os dois eixos. Em cada um, escreva: afirmação → explicação → fundamento/exemplo → consequência.');
const connectors=['além disso','ademais','nesse sentido','por outro lado','entretanto','contudo','todavia','assim','desse modo','portanto','logo','diante disso','consequentemente','primeiramente','em segundo lugar'];const connUsed=connectors.filter(k=>n.includes(normText(k)));let cohesion=Math.min(15,6+connUsed.length*2);if(connUsed.length<3)add('medium','Pouca sinalização de relações lógicas',`Foram identificados ${connUsed.length} conectivo(s) de progressão entre os mais usuais.`,'Use conectivos apenas quando a relação existir: adição, contraste, causa, consequência ou conclusão. Varie sem “encher” o texto.');
const conclusionMarkers=['portanto','diante disso','assim','desse modo','em síntese','em sintese','logo','por fim'];const hasConclusion=conclusionMarkers.some(k=>normText(last).includes(normText(k)))&&writingWords(last).length>=25;let conclusion=hasConclusion?10:5;if(!hasConclusion)add('medium','Conclusão pode fechar melhor o raciocínio','O último parágrafo não apresenta claramente um fechamento da tese ou está curto.','Retome a tese com outras palavras e responda ao comando. Não abra argumento novo na última linha.');
let language=15;const informal=[['eu acho','Substitua opinião pessoal explícita por formulação objetiva, sustentada por argumento.','“Observa-se que...” ou apresente diretamente a tese.'],['na minha opinião','Evite marcador pessoal desnecessário.','Apresente a posição como tese argumentada.'],['a gente','Registro informal.','Use “a sociedade”, “a Administração”, “os cidadãos” ou o sujeito exato.'],[' pra ','Contração informal.','Use “para”.'],[' tá ','Forma coloquial.','Use “está”.'],[' né','Marca de oralidade.','Retire e complete a afirmação.'],['tipo assim','Marca de oralidade.','Substitua por relação lógica objetiva.'],['coisa','Vocabulário vago.','Nomeie exatamente o fenômeno, medida, risco ou consequência.']];informal.forEach(([pat,fix,ex])=>{if(n.includes(normText(pat))){language-=2;add('high',`Registro inadequado: “${pat.trim()}”`,'Expressão coloquial ou vaga reduz precisão e formalidade.',fix,ex)}});
const mechanical=[];if(/\s+[,.;:!?]/.test(text))mechanical.push('há espaço indevido antes de sinal de pontuação');if(/[,;:](?=\S)/.test(text))mechanical.push('há pontuação sem espaço depois');if(/[!?.,]{2,}/.test(text))mechanical.push('há sinais de pontuação repetidos');if(/ {2,}/.test(text))mechanical.push('há espaços duplos');if(mechanical.length){language-=Math.min(4,mechanical.length);add('medium','Revisão mecânica necessária',mechanical.join('; ')+'.','Faça uma leitura exclusiva de pontuação e formatação antes de entregar.');}
const long=sent.map(x=>writingWords(x).length).filter(x=>x>45).length;if(long){language-=Math.min(3,long);add('medium','Períodos longos demais',`${long} período(s) ultrapassam aproximadamente 45 palavras.`,'Divida períodos quando houver muitas orações subordinadas. Uma ideia principal por período melhora clareza.');}
const stop=new Set('a o as os de da do das dos e em para por com que um uma uns umas no na nos nas ao aos à às se ser como mais mas ou sua seu suas seus é são foi foram isso esse essa este esta também já não sobre entre quando onde muito pela pelo pelos pelas'.split(' '));const freq={};writingWords(n).filter(w=>w.length>4&&!stop.has(w)).forEach(w=>freq[w]=(freq[w]||0)+1);const rep=Object.entries(freq).sort((a,b)=>b[1]-a[1]).filter(x=>x[1]>=6).slice(0,3);if(rep.length){language-=2;add('low','Repetição vocabular',`Palavras repetidas com frequência: ${rep.map(x=>`${x[0]} (${x[1]}x)`).join(', ')}.`,'Substitua apenas quando houver sinônimo preciso ou reestruture a frase; não troque termo técnico só para variar.');}
if(words.length<180)add('high','Texto curto para o treino',`Foram contadas ${words.length} palavras.`,'Desenvolva melhor as relações de causa, fundamento e consequência. Neste simulador, busque aproximadamente 25–30 linhas, sem enrolação.');if(words.length>420)add('medium','Texto muito extenso para a configuração de treino',`Foram contadas ${words.length} palavras.`,'Corte exemplos redundantes e repetições. Em prova, respeite exatamente a extensão determinada pelo edital.');
language=Math.max(2,language);argument=Math.min(20,argument);const total=Math.round(adherence+structure+argument+cohesion+language+conclusion);if(!issues.length)add('ok','Estrutura consistente no diagnóstico automático','Nenhum alerta estrutural importante foi detectado.','Faça ainda uma revisão humana de gramática, precisão conceitual e aderência fina ao comando.');return {score:Math.max(0,Math.min(100,total)),words:words.length,pars:pars.length,adherence,structure,argument,cohesion,language,conclusion,issues,aspectStatus,connectors:connUsed}}
function correctionLabel(score){return score>=85?'Muito consistente':score>=70?'Bom caminho':score>=55?'Estrutura intermediária':'Precisa de reescrita'}
function renderWritingCorrection(r,t,bankId){const bank=WRITING_BANKS[bankId];const metrics=[['Aderência ao comando',r.adherence,20],['Estrutura',r.structure,20],['Tese e argumentação',r.argument,20],['Coesão',r.cohesion,15],['Linguagem formal',r.language,15],['Conclusão',r.conclusion,10]];$('#writingCorrection').classList.remove('hidden');$('#writingCorrection').innerHTML=`<div class="correction-hero"><div class="correction-score"><b>${r.score}</b><span>/100 TREINO</span></div><div><span class="kicker">DIAGNÓSTICO • ${bank.name}</span><h2>${correctionLabel(r.score)}</h2><p>${bank.tip}</p><p class="correction-disclaimer">Pontuação heurística para treino. Não reproduz fórmula oficial de nenhum edital e não substitui correção humana.</p></div></div><div class="rubric-grid">${metrics.map(([n,v,m])=>`<div class="rubric-item"><div><span>${n}</span><b>${v}/${m}</b></div><i><em style="width:${Math.round(v/m*100)}%"></em></i></div>`).join('')}</div><section class="correction-section"><h3>Atendimento aos aspectos do tema</h3><div class="aspect-check">${r.aspectStatus.map(x=>`<span class="${x.ok?'':'miss'}"><b>${x.ok?'✓':'!'}</b>${esc(x.label)}</span>`).join('')}</div></section><section class="correction-section"><h3>Erros e como consertar</h3>${r.issues.map(i=>`<article class="correction-issue ${i.severity}"><strong>${esc(i.title)}</strong><p>${esc(i.why)}</p><p class="fix"><b>Como consertar:</b> ${esc(i.fix)}</p>${i.example?`<p><b>Exemplo de direção:</b> ${esc(i.example)}</p>`:''}</article>`).join('')}</section><section class="correction-section"><h3>Plano de reescrita</h3><div class="rewrite-guide"><p><b>Introdução:</b> delimite “${esc(t.title)}” e escreva uma tese que conecte ${esc(t.axes[0])} a ${esc(t.axes[1])}.</p><p><b>Desenvolvimento 1:</b> prove o eixo “${esc(t.axes[0])}” com mecanismo + fundamento + consequência.</p><p><b>Desenvolvimento 2:</b> desenvolva “${esc(t.axes[1])}” sem repetir o primeiro argumento.</p><p><b>Conclusão:</b> responda novamente ao comando em síntese. Acrescente proposta concreta apenas se o comando exigir.</p></div></section>`;$('#writingCorrection').scrollIntoView({behavior:'smooth',block:'start'})}
function renderWritingHistory(){const h=load(LS.writingHistory,[]);if(!$('#writingHistory'))return;$('#writingHistory').innerHTML=h.length?h.slice(0,6).map(x=>`<article class="history-card"><b>${x.score}/100</b><strong>${esc(x.title)}</strong><span>${esc(x.bank)} • ${new Date(x.at).toLocaleDateString('pt-BR')} • ${x.words} palavras</span></article>`).join(''):'<p style="color:var(--muted)">Nenhuma redação corrigida ainda.</p>'}
function resetWritingTimer(){clearInterval(writingTimerHandle);writingSeconds=3600;if($('#writingTimer'))$('#writingTimer').textContent='60:00'}
function tickWritingTimer(){writingSeconds--;const m=Math.max(0,Math.floor(writingSeconds/60)),s=Math.max(0,writingSeconds%60);$('#writingTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;if(writingSeconds<=0){clearInterval(writingTimerHandle);toast('Tempo de redação encerrado')}}

function renderReview(){const d=done().filter(id=>D.lessons.some(l=>l.id===id)),e=errors(),f=fav();$('#reviewSummary').innerHTML=`<article class="review-stat"><b>${e.length}</b><span>questões no caderno de erros</span></article><article class="review-stat"><b>${f.length}</b><span>aulas salvas para revisão</span></article><article class="review-stat"><b>${d.length}/${D.lessons.length}</b><span>aulas concluídas</span></article>`;$('#reviewErrors').innerHTML=e.length?e.slice(0,40).map(x=>`<details class="error-card"><summary><div><span class="error-meta">${esc(x.origin)} • ${esc(x.subject)}</span><h4>${esc(x.title)}</h4></div><span>＋</span></summary><div class="error-detail"><p><strong>Contexto:</strong> ${esc(x.context||'—')}</p><p><strong>Sua justificativa:</strong> ${esc(x.reason||'Não registrada')}</p><p><strong>Correção:</strong> ${esc(x.comment||'Reveja a aula correspondente.')}</p>${x.trap?`<p><strong>Pegadinha:</strong> ${esc(x.trap)}</p>`:''}${x.foundation?`<p><strong>Fundamento:</strong> ${esc(x.foundation)}</p>`:''}${x.foundationUrl?`<a class="foundation-link" href="${x.foundationUrl}" target="_blank">Abrir fonte ↗</a>`:''}</div></details>`).join(''):'<div class="result-panel">Nenhum erro salvo ainda.</div>';const favLessons=f.map(id=>D.lessons.find(l=>l.id===id)).filter(Boolean);$('#reviewFavorites').innerHTML=favLessons.length?favLessons.slice(0,9).map(lessonCard).join(''):'<p style="color:var(--muted)">Nenhuma aula salva.</p>';const rem=lessons(currentCareer).filter(l=>!d.includes(l.id));$('#reviewNext').innerHTML=rem.slice(0,6).map(lessonCard).join('')}
$('#clearErrors').onclick=()=>{if(confirm('Deseja apagar todo o Caderno de Erros?')){save(LS.errors,[]);renderReview();renderHome()}};

function renderReference(){renderProfiles();renderSyllabus();renderSources()}
function renderProfiles(){$('#examProfiles').innerHTML=PROFILES.map(p=>{const max=Math.max(...p.dist.map(x=>x[1]));return `<article class="exam-profile"><div class="exam-profile-head"><div><span class="kicker">${p.short} • ${p.year}</span><h3>${p.title}</h3><p>${p.board} • ${p.format}</p></div><div class="exam-total">${p.total}</div></div><div class="exam-bars">${p.dist.map(([s,n])=>`<div class="exam-bar-row"><div class="exam-bar-label"><span>${s}</span><b>${n}</b></div><div class="exam-bar-line"><i style="width:${Math.round(n/max*100)}%"></i></div></div>`).join('')}</div><div class="exam-note">${p.note}</div><div class="exam-links"><a class="btn secondary compact" href="${p.official}" target="_blank" rel="noopener">Fonte oficial ↗</a><a class="text-btn" href="${p.analysis}" target="_blank" rel="noopener">Análise da distribuição ↗</a></div></article>`}).join('')}
function renderSyllabus(){$('#syllabusList').innerHTML=D.syllabus.map(s=>`<section class="syllabus-career"><span class="kicker">${esc(s.title)}</span><h3>${esc(s.base)}</h3><p>${esc(s.update)}</p>${s.subjects.map(x=>`<details class="syllabus-subject"><summary>${esc(x.name)} • ${x.items.length} blocos</summary><ul>${x.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></details>`).join('')}</section>`).join('')}
function renderSources(){const extra=[...PROFILES.map(p=>({title:`${p.title} — fonte da última prova`,url:p.official,tag:'PROVA OFICIAL'})),{title:'PCDF — Regimento Interno (Resolução nº 8/2025)',url:'https://www.sinj.df.gov.br/sinj/Norma/dbe1096798f04ffcbefd5ec1b3cc1e87/pcdf_cspc_res_08_2025_rep.html',tag:'NORMA VIGENTE'},{title:'Lei nº 14.133/2021 — Licitações e Contratos',url:'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm',tag:'LEI SECA'},{title:'Cebraspe — exemplo recente de prova por itens C/E e critério +1/−1/0',url:'https://cdn.cebraspe.org.br/concursos/ANSA_26/arquivos/3969A00660D0B4D434998AC83CDA12E570D28CC2D67C47C6FDF6C58697C33FB1.html',tag:'PERFIL DE BANCA'},{title:'Quadrix — características oficiais da prova objetiva',url:'https://ajuda.quadrix.org.br/pt-BR/articles/8185616-informacoes-sobre-a-prova-objetiva',tag:'PERFIL DE BANCA'},{title:'Cebraspe — critérios recentes de prova discursiva',url:'https://cdn.cebraspe.org.br/concursos/ANSA_26/arquivos/3969A00660D0B4D434998AC83CDA12E570D28CC2D67C47C6FDF6C58697C33FB1.html',tag:'REDAÇÃO / DISCURSIVA'},{title:'Quadrix — informações oficiais sobre prova discursiva',url:'https://ajuda.quadrix.org.br/pt-BR/articles/8185658-informacoes-sobre-a-prova-discursiva',tag:'REDAÇÃO / DISCURSIVA'}],seen=new Set(),list=[...extra,...D.sources].filter(x=>x.url&&!seen.has(x.url)&&seen.add(x.url));$('#sourceList').innerHTML=list.map(s=>`<article class="source-card"><strong>${esc(s.title)}</strong><span>${esc(s.tag||'FONTE')}</span><a href="${s.url}" target="_blank" rel="noopener">Abrir fonte ↗</a></article>`).join('')}



$('#writingBank').onchange=()=>{$('#writingText').value='';['planThesis','planArg1','planArg2','planConclusion'].forEach(id=>$('#'+id).value='');renderWriting()};
$('#writingTheme').onchange=()=>{$('#writingText').value='';['planThesis','planArg1','planArg2','planConclusion'].forEach(id=>$('#'+id).value='');renderWritingPrompt();updateWritingMetrics()};
$('#randomWritingTheme').onclick=()=>{const bank=$('#writingBank').value,themes=WRITING_THEMES[bank],current=$('#writingTheme').value,others=themes.filter(t=>t.id!==current),pick=(others.length?others:themes)[Math.floor(Math.random()*(others.length||themes.length))];$('#writingTheme').value=pick.id;$('#writingText').value='';['planThesis','planArg1','planArg2','planConclusion'].forEach(id=>$('#'+id).value='');renderWritingPrompt();updateWritingMetrics()};
$('#writingText').oninput=updateWritingMetrics;
$('#insertSkeleton').onclick=()=>{if($('#writingText').value.trim()&&!confirm('O editor já contém texto. Deseja substituir pelo esqueleto?'))return;$('#writingText').value=skeletonForTheme();updateWritingMetrics();toast('Esqueleto inserido — substitua os marcadores pelo seu texto')};
$('#saveWriting').onclick=()=>saveWritingDraft(false);
$('#clearWriting').onclick=()=>{if(confirm('Limpar redação e planejamento deste tema?')){$('#writingText').value='';['planThesis','planArg1','planArg2','planConclusion'].forEach(id=>$('#'+id).value='');$('#writingCorrection').classList.add('hidden');updateWritingMetrics();resetWritingTimer()}};
$('#startWritingTimer').onclick=()=>{resetWritingTimer();writingTimerHandle=setInterval(tickWritingTimer,1000);toast('Cronômetro de 60 minutos iniciado')};
$('#correctWriting').onclick=()=>{const text=$('#writingText').value.trim(),t=writingTheme(),bankId=$('#writingBank').value;if(text.length<80){toast('Escreva um texto maior antes de corrigir');return}saveWritingDraft(true);const r=analyzeWriting(text,t,bankId);renderWritingCorrection(r,t,bankId);let h=load(LS.writingHistory,[]);h.unshift({score:r.score,title:t.title,bank:WRITING_BANKS[bankId].name,at:Date.now(),words:r.words});save(LS.writingHistory,h.slice(0,20));renderWritingHistory()};

function init(){populateCareerSelects();populateSubjects($('#learnSubject'),currentCareer);populateSubjects($('#practiceSubject'),currentCareer);$('#learnCareer').value=currentCareer;$('#practiceCareer').value=currentCareer;renderHome();renderLearn();renderReview();renderSimCards();renderWriting();progress()}
init();
